#include <stdio.h>

#define MAX_OBS 4

int main(void) {
    int obs[MAX_OBS];
    int frame, i;
    int score = 0;

    for (i = 0; i < MAX_OBS; i++) {
        obs[i] = -1;
    }

    for (frame = 0; frame < 5; frame++) {
        for (i = 0; i < MAX_OBS; i++) {
            if (obs[i] != -1) {
                obs[i]--;
                if (obs[i] < 0) {
                    obs[i] = -1;
                    score++;
                }
            }
        }
        if (frame % 2 == 0) {
            for (i = 0; i < MAX_OBS; i++) {
                if (obs[i] == -1) {
                    obs[i] = 2;
                    break;
                }
            }
        }
    }
    printf("%d %d %d %d  score %d\n", obs[0], obs[1], obs[2], obs[3], score);
    return 0;
}

#include <stdio.h>

typedef enum { STATE_MENU, STATE_PLAYING, STATE_GAME_OVER } GameState;

int main(void) {
    char keys[] = ".x.hxr";   /* '.' means no key */
    GameState state = STATE_MENU;
    int frame;

    for (frame = 0; frame < 6; frame++) {
        int key = keys[frame];
        switch (state) {
        case STATE_MENU:
            if (key != '.') state = STATE_PLAYING;
            break;
        case STATE_PLAYING:
            if (key == 'h') state = STATE_GAME_OVER;
            break;
        case STATE_GAME_OVER:
            if (key == 'r') state = STATE_PLAYING;
            break;
        }
        printf("frame %d: state %d\n", frame, state);
    }
    return 0;
}

#include <stdio.h>

typedef struct {
    int score;
    int frame;
} Runner;

void runner_update(Runner* r) {
    r->score++;
    r->frame++;
}

void runner_render(const Runner* r) {
    printf("score %d, frame %d\n", r->score, r->frame);
}

int main(void) {
    Runner r;
    r.score = 0;
    r.frame = 0;
    runner_update(&r);
    runner_update(&r);
    runner_render(&r);
    return 0;
}

